settings.custom_liquid:
{%- comment -%} NAW policy page typography tidy (privacy / terms / refund / shipping) {%- endcomment -%}
<style>
  .shopify-policy__container{max-width:760px !important;margin:0 auto !important;padding:26px 22px 64px !important;font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}
  .shopify-policy__title{margin:20px 0 6px !important;text-align:left !important}
  .shopify-policy__title h1{font-size:clamp(30px,5vw,42px) !important;font-weight:800 !important;letter-spacing:-0.02em !important;line-height:1.08 !important;color:#111 !important;margin:0 !important;text-transform:none !important}
  .shopify-policy__body{border-top:1px solid #e8e8e8;padding-top:26px;margin-top:16px}
  .shopify-policy__body .rte{font-size:15.5px;line-height:1.75;color:#3a3a3a}
  .shopify-policy__body .rte p{margin:0 0 16px}
  .shopify-policy__body .rte h1,.shopify-policy__body .rte h2{font-size:20px;font-weight:700;letter-spacing:-0.01em;color:#111;margin:34px 0 12px;line-height:1.3}
  .shopify-policy__body .rte h3,.shopify-policy__body .rte h4{font-size:16px;font-weight:700;color:#111;margin:24px 0 10px}
  .shopify-policy__body .rte strong,.shopify-policy__body .rte b{color:#111;font-weight:600}
  .shopify-policy__body .rte ul,.shopify-policy__body .rte ol{margin:0 0 16px;padding-left:22px}
  .shopify-policy__body .rte li{margin:6px 0;line-height:1.7}
  .shopify-policy__body .rte li::marker{color:#9a9a9a}
  .shopify-policy__body .rte a{color:#111;text-decoration:underline;text-underline-offset:2px}
  .shopify-policy__body .rte a:hover{color:#000}
  .shopify-policy__body .rte hr{border:0;border-top:1px solid #e8e8e8;margin:30px 0}
  .shopify-policy__body .rte table{border-collapse:collapse;width:100%;margin:0 0 18px;font-size:14px}
  .shopify-policy__body .rte td,.shopify-policy__body .rte th{border:1px solid #e8e8e8;padding:9px 12px;text-align:left}
  @media(max-width:600px){
    .shopify-policy__container{padding:18px 18px 46px !important}
    .shopify-policy__body .rte{font-size:15px}
    .shopify-policy__body{padding-top:20px}
  }
</style>
